/**
 * A SIP endpoint that answers whatever jambonz dials it and then sends a continuous
 * PCMU tone. Both legs of the test call it, so the media the recorder is supposed to
 * be forked is generated by the test itself rather than by whoever is holding a phone.
 */

const dgram = require('dgram');
const Emitter = require('events');
const {parseMsg, buildResponse, sdpMedia} = require('./sip');

const PTIME_MS = 20;
const SAMPLES = 160;            // 20ms of 8kHz

const linearToUlaw = (sample) => {
  const BIAS = 0x84;
  const sign = (sample >> 8) & 0x80;
  if (sign) sample = -sample;
  if (sample > 32635) sample = 32635;
  sample += BIAS;
  let exponent = 7;
  for (let mask = 0x4000; (sample & mask) === 0 && exponent > 0; exponent--, mask >>= 1);
  const mantissa = (sample >> (exponent + 3)) & 0x0f;
  return (~(sign | (exponent << 4) | mantissa)) & 0xff;
};

/* one second of 440Hz, so the payload is real audio rather than silence */
const TONE = (() => {
  const buf = Buffer.alloc(8000);
  for (let i = 0; i < 8000; i++) {
    buf[i] = linearToUlaw(Math.round(8000 * Math.sin(2 * Math.PI * 440 * i / 8000)));
  }
  return buf;
})();

class FakeEndpoint extends Emitter {
  constructor(logger, {sipPort, rtpPortBase, advertiseIp}) {
    super();
    this.logger = logger;
    this.sipPort = sipPort;
    this.rtpPortBase = rtpPortBase;
    this.advertiseIp = advertiseIp;
    this.calls = new Map();
    this.nextRtpPort = rtpPortBase;
    this.answered = 0;
  }

  async start() {
    this.sip = dgram.createSocket('udp4');
    this.sip.on('message', (msg, rinfo) => this._onSip(msg, rinfo));
    await new Promise((resolve) => this.sip.bind(this.sipPort, resolve));
    this.logger(`fake endpoint listening on sip:${this.advertiseIp}:${this.sipPort}`);
  }

  async stop() {
    for (const call of this.calls.values()) this._teardown(call);
    this.sip?.close();
  }

  uri(user) { return `sip:${user}@${this.advertiseIp}:${this.sipPort}`; }

  _onSip(msg, rinfo) {
    const req = parseMsg(msg);
    if (req.startLine.startsWith('SIP/2.0')) return;
    const callId = req.headers['call-id'];

    switch (req.method) {
      case 'INVITE': {
        const existing = this.calls.get(callId);
        const media = sdpMedia(req.body)[0];
        if (!media) return this._send(buildResponse(req, 488, 'Not Acceptable Here'), rinfo);

        const call = existing || this._newCall(callId);
        call.remote = {address: media.ip, port: media.port};
        call.payload = media.payloads.includes('0') ? 0 : parseInt(media.payloads[0], 10);
        const body = this._answerSdp(call);
        this._send(buildResponse(req, 200, 'OK', {
          body, contentType: 'application/sdp', toTag: call.toTag,
          contact: `${this.advertiseIp}:${this.sipPort}`
        }), rinfo);
        if (!existing) {
          this.answered++;
          this.logger(`fake endpoint answered ${req.uri} (call-id ${callId})`);
          this.emit('answered', callId);
        }
        return;
      }
      case 'ACK':
        return this._startMedia(this.calls.get(callId));
      case 'BYE': {
        const call = this.calls.get(callId);
        if (call) this._teardown(call);
        this.emit('bye', callId);
        return this._send(buildResponse(req, 200, 'OK', {toTag: call?.toTag}), rinfo);
      }
      case 'OPTIONS':
        return this._send(buildResponse(req, 200, 'OK'), rinfo);
      default:
        return this._send(buildResponse(req, 200, 'OK'), rinfo);
    }
  }

  _newCall(callId) {
    const call = {
      callId,
      toTag: `ep-${Math.random().toString(36).slice(2, 10)}`,
      rtpPort: this.nextRtpPort,
      seq: Math.floor(Math.random() * 1000),
      ts: 0,
      ssrc: Math.floor(Math.random() * 0xffffffff),
      offset: 0,
      sent: 0,
      received: 0,
      socket: dgram.createSocket('udp4'),
      version: 1
    };
    this.nextRtpPort += 2;
    call.socket.on('message', () => call.received++);
    call.socket.bind(call.rtpPort);
    this.calls.set(callId, call);
    return call;
  }

  _answerSdp(call) {
    return [
      'v=0',
      `o=- ${Date.now()} ${call.version++} IN IP4 ${this.advertiseIp}`,
      's=jambonz smoke endpoint',
      `c=IN IP4 ${this.advertiseIp}`,
      't=0 0',
      `m=audio ${call.rtpPort} RTP/AVP ${call.payload} 101`,
      `a=rtpmap:${call.payload} ${call.payload === 8 ? 'PCMA' : 'PCMU'}/8000`,
      'a=rtpmap:101 telephone-event/8000',
      'a=sendrecv',
      ''
    ].join('\r\n');
  }

  _startMedia(call) {
    if (!call || call.timer) return;
    call.timer = setInterval(() => {
      const payload = Buffer.alloc(SAMPLES);
      for (let i = 0; i < SAMPLES; i++) {
        payload[i] = TONE[(call.offset + i) % TONE.length];
      }
      call.offset = (call.offset + SAMPLES) % TONE.length;

      const pkt = Buffer.alloc(12 + SAMPLES);
      pkt[0] = 0x80;
      pkt[1] = call.payload & 0x7f;
      pkt.writeUInt16BE(call.seq++ & 0xffff, 2);
      pkt.writeUInt32BE(call.ts, 4);
      pkt.writeUInt32BE(call.ssrc, 8);
      payload.copy(pkt, 12);
      call.ts = (call.ts + SAMPLES) >>> 0;

      call.socket.send(pkt, call.remote.port, call.remote.address, () => {});
      call.sent++;
    }, PTIME_MS);
  }

  _send(msg, rinfo) {
    this.sip.send(Buffer.from(msg), rinfo.port, rinfo.address, (err) => {
      if (err) this.logger(`fake endpoint send error: ${err.message}`);
    });
  }

  _teardown(call) {
    clearInterval(call.timer);
    call.timer = null;
    try { call.socket.close(); } catch (err) { /* already closed */ }
    this.calls.delete(call.callId);
  }
}

module.exports = FakeEndpoint;
